for qname,fn in [('TR',lambda o:[r[8:] for r in o[:8]]),('BL',lambda o:[r[:8] for r in o[8:]]),('BR',lambda o:[r[8:] for r in o[8:]])]:
 q3,q5=fn(o3a),fn(o5a)
 sigsrc=[(x3[r][c],x5[r][c]) for r in range(8) for c in range(8)]
 sigdst=[(q3[r][c],q5[r][c]) for r in range(8) for c in range(8)]
 cnt=collections.Counter(sigsrc)
 pairs=[]
 for d,sig in enumerate(sigdst):
  if cnt[sig]==1: pairs.append((d,sigsrc.index(sig)))
 print(qname,'unique pairs',len(pairs),pairs[:20])
 # fit affine source=(a*d+b) mod64
 fits=[]
 for a in range(64):
  if np.gcd(a,64)!=1: continue
  for b0 in range(64):
   if all((a*d+b0)%64==s for d,s in pairs): fits.append((a,b0))
 print('affine fits',fits[:3],len(fits))

